// ══════════════════════════════════════════════
// BIA · METERSIGHT — Procesador de BD Telemedida
// Ejecuta todos los días a las 7 AM via N8N
// ══════════════════════════════════════════════

const csvText    = $('📊 Leer Google Sheet (CSV)').first().json.csvData;
const htmlIn     = $('📥 Leer HTML actual de Netlify').first().json.htmlTemplate;

if (!csvText) throw new Error('No se pudo leer el Google Sheet');
if (!htmlIn)  throw new Error('No se pudo leer el HTML de Netlify');

// ── Parsear CSV ──
const lines   = csvText.split('\n');
const headers = lines[0].split(',').map(h => h.trim());

const cv = (row, i, d='') => {
  try { const v = (row[i]||'').trim(); return (!v||v==='nan'||v==='NaT'||v==='None') ? d : v; }
  catch { return d; }
};

const ESTADOS_ANOMALOS = new Set([
  'Falla en Medidor','Medidor Quemado','Suspendido',
  'Desenergizado','CT/PT quemado','Desocupado','Hurto'
]);

const records = [];
for (let i = 1; i < lines.length; i++) {
  const row = lines[i].split(',');
  if (row.length < 50) continue;

  const estado = cv(row, 7);
  if (estado !== 'Activo' && !ESTADOS_ANOMALOS.has(estado)) continue;

  const nov_raw = cv(row, 43);
  const nov     = ESTADOS_ANOMALOS.has(estado) ? estado
                : ESTADOS_ANOMALOS.has(nov_raw) ? nov_raw : '';

  const ip_raw  = cv(row, 42);
  const ip_tmr  = ip_raw.toUpperCase() === 'TRUE'  ? 'Sí'
                : ip_raw.toUpperCase() === 'FALSE' ? 'Normal'
                : ['#N/A','N/A'].includes(ip_raw)  ? 'N/A'
                : ip_raw;

  const vm_raw  = cv(row, 57);
  const vm      = vm_raw.toUpperCase() === 'TRUE'  ? 'OK'
                : vm_raw.toUpperCase() === 'FALSE' ? 'NO VÁLIDO' : '';

  const ip_opt  = cv(row, 60);
  const ip_opt_v = ip_opt.toUpperCase() === 'TRUE'  ? 'Sí'
                 : ip_opt.toUpperCase() === 'FALSE' ? 'No' : ip_opt;

  records.push({
    i:  cv(row, 0),
    s:  cv(row, 1),
    niu: cv(row, 2),
    u:  cv(row, 4).slice(0, 45),
    ser: cv(row, 27).replace('.0',''),
    ip:  cv(row, 29),
    mk:  cv(row, 25),
    mo:  cv(row, 26),
    mo2: cv(row, 56),
    vm,
    fx:  parseFloat(cv(row, 35)) || 1,
    ct:  parseFloat(cv(row, 58)) || 1,
    pt:  parseFloat(cv(row, 59)) || 1,
    cx:  cv(row, 23),
    med: cv(row, 24),
    tm:  cv(row, 50),
    sub: cv(row, 51),
    nov,
    ul:  cv(row, 32).slice(0, 16),
    ul_res: cv(row, 55).slice(0, 16),
    d:   cv(row, 13).slice(0, 35),
    c:   cv(row, 12),
    or:  cv(row, 8),
    kw:  parseInt(cv(row, 18)) || 0,
    nt:  parseInt(cv(row, 10)) || 1,
    est: estado,
    ip_tmr,
    ageing: parseFloat(cv(row, 45)) || null,
    bucket: cv(row, 46),
    xm:   cv(row, 47),
    falla: parseInt(cv(row, 48)) || 0,
    falla_venc: cv(row, 49).slice(0, 10),
    accion: cv(row, 52),
    imei:  cv(row, 53).replace('.0',''),
    ip_opt: ip_opt_v,
    ul_opt: cv(row, 61).slice(0, 16),
    val_opt: cv(row, 62),
    tipo_mercado:  cv(row, 9),
    tipo_frontera: cv(row, 21),
    cap_trafo: cv(row, 36),
    comentarios: cv(row, 41).slice(0, 120),
    prueba_tm:  cv(row, 37),
    creado_hes: cv(row, 38),
  });
}

// ── Comprimir a Base64 (N8N no tiene pako, usar btoa) ──
const jsonStr = JSON.stringify(records, null, 0);
// Convertir a base64 (sin gzip en N8N — el cliente descomprime igual)
const db64 = Buffer.from(jsonStr).toString('base64');

// ── Fecha actual Colombia ──
const now = new Date().toLocaleString('es-CO', {
  day:'2-digit', month:'2-digit', year:'numeric',
  hour:'2-digit', minute:'2-digit',
  timeZone: 'America/Bogota'
});
const nowStr = now.replace(',','');

// ── Actualizar HTML ──
let html = htmlIn;

// Reemplazar DB64
html = html.replace(/const DB64="[^"]*";/, `const DB64="${db64}";`);

// Si la BD está comprimida con gzip, necesitamos ajustar la descompresión
// Detectar si usa DecompressionStream (gzip) o atob directo
const usesGzip = html.includes('DecompressionStream');

if (usesGzip) {
  // Reemplazar la función de descompresión por atob directo (ya que N8N no puede gzip)
  html = html.replace(
    /\(async\(\)=>\{[\s\S]*?DB=JSON\.parse[\s\S]*?\}\)\(\);/,
    `(async()=>{
  try{
    const jsonStr = atob(DB64);
    DB = JSON.parse(jsonStr);
    buildChips();
  }catch(e){console.error('DB:',e);}
})();`
  );
}

// Actualizar fecha en footer
html = html.replace(/BD Telemedida · [\d\/]+ [\d:]+/g, `BD Telemedida · ${nowStr}`);

// Actualizar conteo
html = html.replace(/[\d,]+ fronteras activas/g, `${records.length.toLocaleString('es-CO')} fronteras activas`);
html = html.replace(/[\d,]+ fronteras/g, `${records.length.toLocaleString('es-CO')} fronteras`);

return [{
  json: {
    html,
    filename: 'index.html',
    records_count: records.length,
    updated: nowStr,
    db64_size_kb: Math.round(db64.length / 1024)
  }
}];

